const formulas=[
{id:"wavelength",title:"Wavelength",method:"UT",equation:"λ = v / f",description:"Wavelength equals wave velocity divided by frequency. Use the velocity for the correct material and wave mode.",inputs:[["v","Velocity (m/s)",5920],["f","Frequency (MHz)",5]],calc:x=>({value:x.v/(x.f*1e6)*1000,unit:"mm"})},
{id:"thickness",title:"Pulse-echo thickness",method:"UT",equation:"d = v × t / 2",description:"The pulse travels to the back wall and returns, so divide the round-trip distance by two.",inputs:[["v","Material velocity (m/s)",5920],["t","Round-trip time (µs)",10]],calc:x=>({value:x.v*x.t/2/1000,unit:"mm"})},
{id:"velocity",title:"Wave velocity",method:"UT",equation:"v = f × λ",description:"Frequency multiplied by wavelength gives wave velocity when the units are consistent.",inputs:[["f","Frequency (MHz)",2],["lambda","Wavelength (mm)",2.95]],calc:x=>({value:x.f*1e6*x.lambda/1000,unit:"m/s"})},
{id:"decibels",title:"Amplitude ratio",method:"UT / PAUT",equation:"ΔG = 20 log₁₀(A₂ / A₁)",description:"The decibel difference for voltage-like signal amplitudes is based on the amplitude ratio.",inputs:[["a2","Amplitude 2 (%)",80],["a1","Amplitude 1 (%)",40]],calc:x=>({value:20*Math.log10(x.a2/x.a1),unit:"dB"})},
{id:"impedance",title:"Acoustic impedance",method:"UT",equation:"Z = ρ × v",description:"Acoustic impedance is density multiplied by sound velocity for the relevant wave mode.",inputs:[["rho","Density (kg/m³)",7850],["v","Velocity (m/s)",5900]],calc:x=>({value:x.rho*x.v,unit:"kg/(m²·s)"})},
{id:"skin",title:"Eddy-current skin depth",method:"ET",equation:"δ = √(2 / (ω μ σ))",description:"Skin depth is an approximate characteristic depth for electromagnetic fields in a homogeneous conductor. Requires frequency, permeability and conductivity in consistent SI units.",inputs:[["f","Frequency (Hz)",100000],["mu","Permeability (H/m)",0.000001256637],["sigma","Conductivity (S/m)",58000000]],calc:x=>({value:Math.sqrt(2/(2*Math.PI*x.f*x.mu*x.sigma))*1000,unit:"mm"})},
{id:"inverse",title:"Inverse-square exposure relationship",method:"RT",equation:"I₁ / I₂ = (r₂ / r₁)²",description:"For a point-source approximation in a consistent geometry, intensity varies inversely with the square of distance.",inputs:[["r1","Distance 1 (m)",1],["r2","Distance 2 (m)",2]],calc:x=>({value:(x.r2/x.r1)**2,unit:"I₁ / I₂"})},
{id:"snell",title:"Refraction (Snell's law)",method:"UT / PAUT",equation:"sin θ₁ / v₁ = sin θ₂ / v₂",description:"Relates incident and refracted angles using wave velocities. Confirm the angle convention and wave modes before applying.",inputs:[["theta1","Incident angle (°)",30],["v1","Incident velocity (m/s)",2730],["v2","Refracted velocity (m/s)",3230]],calc:x=>({value:Math.asin(Math.sin(x.theta1*Math.PI/180)*x.v2/x.v1)*180/Math.PI,unit:"° (if real solution)"})}
];
