ut:[["What does the time axis of a conventional A-scan usually represent?","Elapsed time or calibrated sound path","Material hardness","Probe temperature","Surface colour",0,"Echo position is related to travel time and, after calibration, sound path."],["Why is couplant used in contact UT?","To reduce the air gap between probe and component","To increase component hardness","To remove every discontinuity","To replace calibration",0,"Air strongly impedes ultrasound transmission; couplant improves acoustic contact."],["For pulse-echo thickness, why is travel time divided by two?","The pulse travels to the back wall and returns","The probe has two crystals","Velocity is always halved","The display has two axes",0,"The measured pulse-echo time is for the round trip."],["Which factor can strongly affect an angle-beam indication?","Reflector orientation","Screen brightness only","Operator name","File format",0,"Ultrasonic response depends on reflector orientation and beam direction."],["What should determine acceptance of an indication?","Applicable code, specification and approved procedure","A universal colour scale","The loudest echo alone","A generic internet chart",0,"Acceptance criteria must come from the governing requirements and procedure."]],
paut:[["What is the main purpose of a PAUT focal law?","Control element timing to form a desired beam","Change the component chemistry","Replace all calibration","Remove coupling requirements",0,"Focal laws control element delays for steering and focusing."],["What does an encoded PAUT scan record?","Inspection data associated with position","Only the operator's name","Only water temperature","A certificate number",0,"Encoder data ties acquisition to scan position."],["What is a wedge delay correction used for?","Account for travel through the wedge and setup geometry","Measure hardness","Set radiation dose","Demagnetise a component",0,"Wedge delay is part of correct PAUT calibration."],["Why is scan planning necessary?","To demonstrate required volume coverage","To make every indication acceptable","To avoid recording calibration","To guarantee zero false calls",0,"Coverage depends on geometry, beam paths, and procedure requirements."],["What can incorrect focal laws cause?","Misleading beam coverage or indication response","Automatic code compliance","Perfect coupling","No need for verification",0,"Focal-law errors can compromise coverage and interpretation."]],
tofd:[["Which signal is commonly associated with the top surface path in TOFD?","Lateral wave","Gamma line","Lift-off curve","Magnetic particle chain",0,"The lateral wave travels near the component surface between the probes."],["TOFD sizing primarily uses what measurement?","Arrival time of diffracted signals","Penetrant dwell colour only","Coil resistance only","Radiographic film density alone",0,"Signal arrival times are interpreted using geometry and velocity."],["What can create a near-surface TOFD limitation?","Dead zone and overlapping signals","Too much visible light only","High magnetic permeability alone","Incorrect developer",0,"Near-surface signals can overlap or be difficult to separate."],["Why must probe separation be recorded?","It is part of the sound-path geometry","It sets particle colour","It measures conductivity directly","It replaces the velocity setting",0,"Probe separation influences the interpretation geometry."],["What must guide TOFD evaluation?","Applicable procedure and acceptance criteria","A single universal depth limit","Display colour alone","The loudest sound",0,"Evaluation follows the governing procedure and specification."]],
