et:[["Eddy currents are induced in which materials?","Electrically conductive materials","Only transparent plastics","All materials equally","Only wood",0,"Eddy current testing relies on electromagnetic induction in conductive materials."],["What does lift-off commonly describe?","Change in spacing between probe and test surface","Material density","TOFD probe separation","Radiographic dose",0,"Lift-off affects coil response when probe-to-surface distance changes."],["What does skin depth describe?","Characteristic depth of electromagnetic field penetration","Weld cap height only","Ultrasonic skip distance","Film grain size",0,"Skin depth depends on frequency, permeability and conductivity."],["Why use a reference standard in ET?","To verify response under defined conditions","To avoid recording settings","To eliminate all geometry effects","To certify the operator automatically",0,"Reference standards support setup verification and interpretation."],["Which variable changes ET penetration depth?","Test frequency","Page background colour","Certificate layout","Operator email",0,"Higher frequency generally reduces skin depth, all else equal."]],
