const state={view:"home",method:"ut",lesson:0,search:"",user:null,session:null,results:[],progress:readLocal("ndt-new-ui-progress",{}),attempts:readLocal("ndt-new-ui-attempts",[]),formulaFilter:"all"};
function readLocal(k,d){try{return JSON.parse(localStorage.getItem(k)||"null")??d}catch{return d}}
function saveLocal(k,v){try{localStorage.setItem(k,JSON.stringify(v))}catch{}}
function esc(s){return String(s??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function methods(){const raw=window.UTMA_DATA?.methods||[];return primaryIds.map(id=>{const found=raw.find(m=>m.id===id);return {...(found||{}),...methodMeta[id],id}})}
function topics(id){return extraTopics[id]||extraTopics.ut}
function currentMethod(){return methods().find(m=>m.id===state.method)||methods()[0]}
function completedFor(id){return Object.values(state.progress[id]||{}).filter(Boolean).length}
function totalLessons(id){return topics(id).length}
function percent(id){return Math.round(completedFor(id)/totalLessons(id)*100)}
function topicId(title){return title.toLowerCase().replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")}
function route(view,method=state.method,lesson=state.lesson){const u=new URL(location.href);u.searchParams.set("view",view);if(method)u.searchParams.set("method",method);if(lesson!==undefined&&lesson!==null)u.searchParams.set("lesson",String(lesson));else u.searchParams.delete("lesson");history.pushState({view,method,lesson}, "",u);state.view=view;state.method=method||"ut";state.lesson=Number(lesson)||0;render();window.scrollTo({top:0,behavior:"smooth"})}
function parseRoute(){const p=new URLSearchParams(location.search);state.view=p.get("view")||"home";state.method=p.get("method")||"ut";state.lesson=Math.max(0,Number(p.get("lesson")||0));if(!["home","methods","learning","lesson","formulas","practice","progress","about"].includes(state.view))state.view="home";if(!primaryIds.includes(state.method))state.method="ut"}
function toast(msg){const el=$("#toast");el.textContent=msg;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2800)}
function sectionHead(kicker,title,description,action=""){return '<div class="section-head"><div><div class="kicker">'+esc(kicker)+'</div><h2>'+esc(title)+'</h2><p>'+esc(description)+'</p></div>'+action+'</div>'}
function methodCard(m){return '<article class="method-card"><div class="method-head"><span class="method-code">'+esc(m.code)+'</span><span class="method-type">'+esc(m.kind)+'</span></div><div class="method-body"><h3>'+esc(m.name)+'</h3><p>'+esc(m.desc)+'</p><div class="progress-track"><span style="width:'+percent(m.id)+'%"></span></div><div class="small">'+percent(m.id)+'% course progress · '+completedFor(m.id)+'/'+totalLessons(m.id)+' lessons</div><button class="btn btn-primary" data-action="start" data-method="'+m.id+'">Start Lesson <span aria-hidden="true">→</span></button></div></article>'}
function heroArt(){return '<div class="hero-art"><svg viewBox="0 0 440 280" role="img" aria-label="Ultrasonic waveform illustration"><defs><linearGradient id="wave" x1="0" x2="1"><stop stop-color="#F4B183"/><stop offset="1" stop-color="#C65D24"/></linearGradient></defs><g stroke="#ffffff24" stroke-width="1"><path d="M20 40H420M20 80H420M20 120H420M20 160H420M20 200H420M20 240H420"/><path d="M60 20V260M120 20V260M180 20V260M240 20V260M300 20V260M360 20V260"/></g><rect x="42" y="72" width="355" height="132" rx="13" fill="#ffffff08" stroke="#ffffff30"/><path d="M55 151H91L108 142L123 151L143 151L160 96L177 195L195 151H242L258 127L276 151H318L336 112L354 151H383" stroke="url(#wave)" stroke-width="4" fill="none" stroke-linecap="round" stroke-linejoin="round"/><path d="M160 96V205M336 112V205" stroke="#F4B183" stroke-opacity=".5" stroke-dasharray="4 5"/><text x="57" y="59" class="art-label">A-SCAN / SIGNAL RESPONSE</text><text x="59" y="226" fill="#f2dfe0" font-size="10">TIME →</text><text x="286" y="226" fill="#f2dfe0" font-size="10">AMPLITUDE ↑</text><circle cx="356" cy="47" r="18" fill="#C65D24" fill-opacity=".24" stroke="#F4B183"/><path d="M347 47h5l4-8 5 16 4-8h3" stroke="#F4B183" stroke-width="2" fill="none" stroke-linecap="round"/></svg></div>'}
function renderHome(){const all=methods();const total=all.reduce((n,m)=>n+totalLessons(m.id),0),done=all.reduce((n,m)=>n+completedFor(m.id),0);return '<section class="hero"><div><div class="eyebrow">A new way to learn inspection science</div><h1>Understand the signal.<br><em>Master the method.</em></h1><p>A structured, self-paced NDT theory academy—from wave physics and inspection principles to advanced methods, formulas and technical practice.</p><div class="hero-actions"><button class="btn btn-light" data-action="nav" data-view="methods">Explore NDT methods →</button><button class="btn btn-ghost" data-action="continue">Continue learning</button></div><div class="small" style="color:#d9c2c5;margin-top:16px">UT · PAUT · TOFD · RT · ET · MT · LPT/PT · VT</div></div>'+heroArt()+'</section><div class="stats"><div class="stat"><span class="stat-icon">◈</span><div><strong>08</strong><span>Core NDT methods</span></div></div><div class="stat"><span class="stat-icon">▤</span><div><strong>'+total+'</strong><span>Structured lessons</span></div></div><div class="stat"><span class="stat-icon">∑</span><div><strong>'+formulas.length+'</strong><span>Key formulas</span></div></div><div class="stat"><span class="stat-icon">✓</span><div><strong>'+done+'/'+total+'</strong><span>Lessons completed</span></div></div></div>'+sectionHead("Explore the academy","Choose your learning path","Each method opens a dedicated curriculum. Start Lesson takes you straight into the first lesson, not a dead-end overview.",'<button class="btn btn-outline" data-action="nav" data-view="methods">All methods →</button>')+'<div class="method-grid">'+all.slice(0,4).map(methodCard).join("")+'</div><section class="section">'+sectionHead("Your learning toolkit","Theory, calculations and practice","Build understanding with worked examples, calculators, and topic-based questions.")+'<div class="grid three"><article class="card"><span class="card-tag">01 / LEARN</span><h3>Learning Academy</h3><p>Structured modules, lesson summaries, examples, and a clear route from fundamentals to advanced topics.</p><button class="btn btn-outline" data-action="nav" data-view="learning">Open curriculum →</button></article><article class="card"><span class="card-tag">02 / CALCULATE</span><h3>Formula Library</h3><p>Search key equations, understand the variables, and calculate with worked steps and units.</p><button class="btn btn-outline" data-action="nav" data-view="formulas">Explore formulas →</button></article><article class="card"><span class="card-tag">03 / PRACTISE</span><h3>Practice Session</h3><p>Answer 25 method-specific questions, review explanations and identify topics to revisit.</p><button class="btn btn-outline" data-action="nav" data-view="practice">Start practice →</button></article></div></section><div class="notice">Educational use only: lessons, quizzes and progress records do not confer ASNT, ISO 9712, Level II or Level III personnel certification.</div>'}
function renderMethods(){return '<section class="page-hero"><div class="eyebrow">NDT method library</div><h1>Choose a method. Start learning.</h1><p>Explore the physical principle, equipment, typical uses and limitations of each method. Every Start Lesson button opens its actual first lesson.</p></section><div class="toolbar"><input class="field" id="methodSearch" placeholder="Search methods or inspection principles…" value="'+esc(state.search)+'"><span class="pill">8 methods</span></div><div class="method-grid" id="methodGrid">'+methods().filter(m=>!state.search||(m.name+" "+m.code+" "+m.desc).toLowerCase().includes(state.search.toLowerCase())).map(methodCard).join("")+'</div>'}
function renderLearning(){return '<section class="page-hero"><div class="eyebrow">Structured curriculum</div><h1>Learning Academy</h1><p>Select a method to view its topic sequence, course progress and lessons. Start Lesson opens lesson one immediately; choosing a topic opens that exact lesson.</p></section><div class="grid two">'+methods().map(m=>'<article class="card"><div class="card-tag">'+esc(m.code)+' · '+esc(m.kind)+'</div><h3>'+esc(m.name)+'</h3><p>'+esc(m.desc)+'</p><div class="progress-track"><span style="width:'+percent(m.id)+'%"></span></div><div class="small">'+completedFor(m.id)+' of '+totalLessons(m.id)+' lessons completed</div><div class="hero-actions" style="margin-top:14px"><button class="btn btn-primary" data-action="start" data-method="'+m.id+'">Start Lesson →</button><button class="btn btn-outline" data-action="course" data-method="'+m.id+'">View syllabus</button></div></article>').join("")+'</div>'}
function renderCourse(){const m=currentMethod(),list=topics(m.id);return '<div class="breadcrumbs"><button data-action="nav" data-view="methods">NDT Methods</button><span>›</span><span>'+esc(m.code)+' syllabus</span></div><section class="page-hero"><div class="eyebrow">'+esc(m.kind)+' · '+esc(m.code)+'</div><h1>'+esc(m.name)+'</h1><p>'+esc(m.desc)+'</p><div class="progress-track"><span style="width:'+percent(m.id)+'%"></span></div><span class="small" style="color:#f3dfe2">'+percent(m.id)+'% complete · '+completedFor(m.id)+' of '+list.length+' lessons</span><div class="hero-actions" style="margin-top:15px"><button class="btn btn-light" data-action="start" data-method="'+m.id+'">Start Lesson →</button></div></section><div class="card"><h3>Course syllabus</h3><p>Choose a topic to open that lesson. Lesson completion is saved locally and synced to your account when you sign in.</p><div class="curriculum">'+list.map((t,i)=>'<button class="curriculum-row" data-action="lesson" data-method="'+m.id+'" data-lesson="'+i+'"><span class="row-number">'+String(i+1).padStart(2,"0")+'</span><span class="row-title"><strong>'+esc(t)+'</strong><small>'+esc(i===0?"Start with the fundamentals":"Theory · terminology · applications · limitations · examples")+'</small></span><span class="row-state">'+(state.progress[m.id]?.[topicId(t)]?"✓ Complete":"Open →")+'</span></button>').join("")+'</div></div>'}
function getMethodContent(m,title,index){const base=m.principle||methodMeta[m.id].principle;const list=m.workflow||["Review the inspection requirement and approved procedure.","Select equipment and reference standards appropriate to the technique.","Verify setup and calibration before examining the component.","Examine the required area with documented coverage.","Record indications, limitations and results against the governing requirements."];return {lead:index===0?m.desc:"This lesson develops "+title.toLowerCase()+" as part of "+m.name+". Use the concepts alongside the method's approved procedure and relevant technical references.",sections:[["Learning objectives",["Explain the purpose of "+title.toLowerCase()+".","Identify the main variables and setup considerations.","Recognise the method's strengths, limitations and common interpretation risks."]],["Principle and terminology",[base]],["Equipment and setup",[m.equipment||methodMeta[m.id].equipment,"Check equipment condition, reference standards, calibration status and suitability for the inspection task."]],["Inspection workflow",list],["Applications and limitations",[m.strengths||methodMeta[m.id].strength,"Important limitations: "+(m.limits||methodMeta[m.id].limits)]],["Worked learning example",["Consider a component with a defined inspection requirement. Identify the target discontinuity or measurement, choose a method and technique suited to the material and geometry, verify the setup against a reference standard, and interpret the observed response under the approved procedure.","The example illustrates the reasoning workflow; it does not establish an acceptance criterion for a real component."]],["Knowledge check",["Can you describe the physical principle in your own words?","Which setup variables can change the indication?","What procedure or acceptance criteria must be consulted before reporting?"]]]}}
function renderLesson(){const m=currentMethod(),list=topics(m.id),idx=Math.min(state.lesson,list.length-1),title=list[idx],id=topicId(title),content=getMethodContent(m,title,idx),pct=percent(m.id),done=!!state.progress[m.id]?.[id];return '<div class="breadcrumbs"><button data-action="nav" data-view="methods">NDT Methods</button><span>›</span><button data-action="course" data-method="'+m.id+'">'+esc(m.code)+' syllabus</button><span>›</span><span>Lesson '+(idx+1)+'</span></div><div class="lesson-layout"><article class="lesson-content"><div class="kicker">'+esc(m.code)+' · LESSON '+String(idx+1).padStart(2,"0")+' / '+list.length+'</div><h1>'+esc(title)+'</h1><p class="lesson-lead">'+esc(content.lead)+'</p>'+content.sections.map((s,i)=>'<section><h2>'+esc(s[0])+'</h2>'+(i===1?'<p>'+esc(s[1][0])+'</p>':i===2||i===4?'<ul>'+s[1].map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>':i===3?'<ol>'+s[1].map(x=>'<li>'+esc(x)+'</li>').join("")+'</ol>':'<ul>'+s[1].map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>')+'</section>').join("")+'<div class="notice">Always follow the governing code, approved written procedure, safety controls and applicable acceptance criteria. This educational lesson does not authorise inspection work.</div><div class="lesson-nav"><button class="btn btn-outline" data-action="lesson" data-method="'+m.id+'" data-lesson="'+Math.max(0,idx-1)+'" '+(idx===0?"disabled":"")+'>← Previous lesson</button><button class="btn '+(done?"btn-outline":"btn-primary")+'" data-action="complete" data-method="'+m.id+'" data-lesson="'+idx+'">'+(done?"✓ Completed":"Mark as complete")+'</button><button class="btn btn-primary" data-action="lesson" data-method="'+m.id+'" data-lesson="'+Math.min(list.length-1,idx+1)+'" '+(idx===list.length-1?"disabled":"")+'>Next lesson →</button></div></article><aside class="lesson-aside"><div class="kicker">YOUR COURSE</div><h3>'+esc(m.name)+'</h3><p>'+pct+'% completed</p><div class="progress-track"><span style="width:'+pct+'%"></span></div><p><strong>Lesson navigation</strong></p><ul>'+list.map((t,i)=>'<li><button class="lesson-side-link '+(i===idx?"current":"")+'" data-action="lesson" data-method="'+m.id+'" data-lesson="'+i+'">'+(state.progress[m.id]?.[topicId(t)]?"✓ ":"")+esc(t)+'</button></li>').join("")+'</ul><button class="btn btn-outline" style="width:100%" data-action="course" data-method="'+m.id+'">Full syllabus</button></aside></div>'}
function renderFormulas(){const q=state.search.toLowerCase();const shown=formulas.filter(f=>(state.formulaFilter==="all"||f.method.toLowerCase().includes(state.formulaFilter))&&(!q||(f.title+" "+f.equation+" "+f.description+" "+f.method).toLowerCase().includes(q)));return '<section class="page-hero"><div class="eyebrow">Formula Library</div><h1>Understand the equation.</h1><p>Search technical formulas, inspect variables and units, and use the built-in calculator to see the result with your own values.</p></section><div class="toolbar"><input class="field" id="formulaSearch" value="'+esc(state.search)+'" placeholder="Search formulas, variables or method…"><select class="field" id="formulaFilter" style="max-width:220px"><option value="all">All methods</option>'+["ut","paut","tofd","rt","et","mt","pt","vt"].map(x=>'<option value="'+x+'" '+(state.formulaFilter===x?"selected":"")+'>'+x.toUpperCase()+'</option>').join("")+'</select></div><div class="formula-grid">'+shown.map(f=>'<article class="formula-card"><span class="card-tag">'+esc(f.method)+'</span><h3>'+esc(f.title)+'</h3><div class="equation">'+esc(f.equation)+'</div><p>'+esc(f.description)+'</p><div class="calc-fields">'+f.inputs.map(([key,label,value])=>'<label>'+esc(label)+'<input type="number" step="any" data-formula-input="'+f.id+'" data-key="'+key+'" value="'+value+'"></label>').join("")+'</div><div class="calc-result" id="result-'+f.id+'">Result appears here</div><button class="btn btn-primary" data-action="calculate" data-id="'+f.id+'" style="margin-top:10px">Calculate</button><button class="btn btn-outline" data-action="formula-reset" data-id="'+f.id+'" style="margin-top:10px">Reset</button></article>').join("")+'</div>'+(shown.length?"":'<div class="empty">No formulas match your search.</div>')}
function renderPractice(){if(state.session)return renderQuiz();return '<section class="page-hero"><div class="eyebrow">Practice session</div><h1>Build confidence one question at a time.</h1><p>Choose an NDT method and complete 25 questions. Your result includes explanations and revision guidance. Practice sessions do not issue certificates.</p></section><div class="grid two"><article class="card"><h3>Start a practice set</h3><label class="small" for="practiceMethod">Select method</label><select id="practiceMethod" class="field" style="margin:8px 0 14px">'+methods().map(m=>'<option value="'+m.id+'">'+esc(m.code+" — "+m.name)+'</option>').join("")+'<option value="all">All NDT Methods — mixed</option></select><p>25 questions · four options · one question at a time · explanations after submission.</p><button class="btn btn-primary" data-action="practice-start">Start 25-question practice →</button></article><article class="card"><h3>Recent attempts</h3>'+(state.attempts.length?state.attempts.slice(-5).reverse().map(a=>'<p><strong>'+esc(a.method.toUpperCase())+'</strong> · '+a.correct+'/'+a.total+' correct · '+a.percent+'% <span class="small">'+new Date(a.date).toLocaleDateString()+'</span></p>').join(""):'<p>No attempts yet. Complete a practice session to see your history here.</p>')+'</article></div><div class="notice">The current practice bank is a learning aid. It is not an official ASNT or ISO 9712 examination.</div>'}
function renderQuiz(){const s=state.session,q=s.questions[s.index];return '<div class="quiz-wrap"><div class="breadcrumbs"><button data-action="nav" data-view="practice">Practice Session</button><span>›</span><span>'+esc(s.method==="all"?"Mixed practice":methodMeta[s.method].code)+'</span></div><div class="quiz-card"><div class="quiz-meta"><span>QUESTION '+(s.index+1)+' OF '+s.questions.length+'</span><span>'+esc(s.method==="all"?"Mixed NDT":methodMeta[s.method].name)+'</span></div><div class="progress-track"><span style="width:'+((s.index+1)/s.questions.length*100)+'%"></span></div><h2>'+esc(q[0])+'</h2><div class="answers">'+q.slice(1,5).map((a,i)=>'<button class="answer '+(s.answers[s.index]===i?"selected":"")+'" data-action="answer" data-answer="'+i+'"><b>'+String.fromCharCode(65+i)+'</b><span>'+esc(a)+'</span></button>').join("")+'</div><div class="hero-actions" style="justify-content:space-between;margin-top:22px"><button class="btn btn-outline" data-action="quiz-prev" '+(s.index===0?"disabled":"")+'>← Previous</button><span class="small" style="align-self:center">'+s.answers.filter(x=>x!==null).length+' answered</span><button class="btn btn-primary" data-action="quiz-next">'+(s.index===s.questions.length-1?"Finish practice":"Next →")+'</button></div></div></div>'}
function renderPracticeResult(){const r=state.results;return '<section class="page-hero"><div class="eyebrow">Practice results</div><h1>'+r.correct+' / '+r.total+' correct · '+r.percent+'%</h1><p>'+esc(r.method==="all"?"Mixed NDT practice":methodMeta[r.method].name)+' · '+(r.percent>=50?"Keep building on your understanding.":"Review the explanations and try another set.")+'</p></section><div class="grid two"><article class="card"><h3>Score summary</h3><p>Correct answers: <strong>'+r.correct+'</strong></p><p>Incorrect or unanswered: <strong>'+(r.total-r.correct)+'</strong></p><p>Percentage: <strong>'+r.percent+'%</strong></p><button class="btn btn-primary" data-action="practice-retry">Try a new set →</button></article><article class="card"><h3>Review answers</h3>'+r.review.map((x,i)=>'<p><strong>'+(i+1)+'. '+esc(x.q)+'</strong><br><span class="small">Correct answer: '+String.fromCharCode(65+x.correct)+'. '+esc(x.options[x.correct])+'</span><br>'+esc(x.explanation)+'</p>').join("")+'</article></div><div class="notice">This is a self-learning practice result only. It is not a formal qualification or personnel certification.</div>'}
function renderProgress(){const all=methods(),total=all.reduce((n,m)=>n+totalLessons(m.id),0),done=all.reduce((n,m)=>n+completedFor(m.id),0);return '<section class="page-hero"><div class="eyebrow">Learning dashboard</div><h1>Your progress, clearly tracked.</h1><p>Lesson completion is saved in this browser. Sign in to sync progress to your Supabase account.</p></section><div class="stats"><div class="stat"><div><strong>'+done+'</strong><span>Lessons complete</span></div></div><div class="stat"><div><strong>'+total+'</strong><span>Total lessons</span></div></div><div class="stat"><div><strong>'+Math.round(done/Math.max(total,1)*100)+'%</strong><span>Overall progress</span></div></div><div class="stat"><div><strong>'+state.attempts.length+'</strong><span>Practice attempts</span></div></div></div><div class="grid two">'+all.map(m=>'<article class="card"><span class="card-tag">'+esc(m.code)+'</span><h3>'+esc(m.name)+'</h3><div class="progress-track"><span style="width:'+percent(m.id)+'%"></span></div><p>'+completedFor(m.id)+' / '+totalLessons(m.id)+' lessons · '+percent(m.id)+'%</p><button class="btn btn-outline" data-action="course" data-method="'+m.id+'">View progress →</button></article>').join("")+'</div><div class="notice">'+(state.user?"Signed in as "+esc(state.user.email)+".":"You are using local progress. Sign in to sync your learning record across devices.")+'</div>'}
function renderAbout(){return '<section class="page-hero"><div class="eyebrow">About the academy</div><h1>Learn NDT theory responsibly.</h1><p>NDT Masterclass Academy is designed to make inspection principles, equipment, formulas, applications and limitations easier to study.</p></section><div class="grid two"><article class="card"><h3>What you can learn</h3><p>UT, PAUT, TOFD, RT, ET, MT, LPT/PT and VT, with structured lessons, formula explanations, calculators and practice questions.</p></article><article class="card"><h3>What this platform is not</h3><p>Completing lessons or quizzes does not provide ASNT, ISO 9712, Level II or Level III personnel certification, employer authorisation or practical competence.</p></article></div>'}
function render(){const root=$("#app");if(!root)return;const views={home:renderHome,methods:renderMethods,learning:renderLearning,course:renderCourse,lesson:renderLesson,formulas:renderFormulas,practice:renderPractice,progress:renderProgress,about:renderAbout};root.innerHTML=(views[state.view]||renderHome)();$$("[data-nav]").forEach(b=>b.classList.toggle("active",b.dataset.nav===state.view||(state.view==="course"&&b.dataset.nav==="learning")));document.title=(state.view==="lesson"?topics(state.method)[state.lesson]+" · ":"")+ "NDT Masterclass Academy";if(state.view==="formulas")$$("[data-action='calculate']").forEach(b=>calcFormula(b.dataset.id))}
function startLesson(id){state.method=primaryIds.includes(id)?id:"ut";route("lesson",state.method,0)}
function saveProgress(method,lessonIndex){const title=topics(method)[lessonIndex];state.progress[method]=state.progress[method]||{};state.progress[method][topicId(title)]=true;saveLocal("ndt-new-ui-progress",state.progress);if(supabase&&state.user){supabase.from("academy_method_lesson_progress").upsert({user_id:state.user.id,method_id:method,lesson_id:topicId(title),completed:true,completed_at:new Date().toISOString(),updated_at:new Date().toISOString()},{onConflict:"user_id,method_id,lesson_id"}).then(({error})=>{if(error)console.warn("Progress sync did not complete:",error.message)})}toast("Lesson marked complete");render()}
function calcFormula(id){const f=formulas.find(x=>x.id===id);if(!f)return;const vals={};for(const [key] of f.inputs){const el=$('[data-formula-input="'+id+'"][data-key="'+key+'"]');vals[key]=Number(el?.value)}if(Object.values(vals).some(x=>!Number.isFinite(x))||f.inputs.some(([k])=>!Number.isFinite(vals[k]))){$("#result-"+id).textContent="Enter valid numbers in every field.";return}if(["f","t","a1","r1","mu","sigma"].some(k=>k in vals&&vals[k]<=0)||["lambda","v","a2","r2","rho"].some(k=>k in vals&&vals[k]<=0)){if(Object.values(vals).some(v=>v<=0)){$("#result-"+id).textContent="Values must be greater than zero for this formula.";return}}let result;try{result=f.calc(vals)}catch{result=null}if(!result||!Number.isFinite(result.value)){$("#result-"+id).textContent="No valid real result for these inputs. Check values and assumptions.";return}$("#result-"+id).textContent="Result: "+Number(result.value.toPrecision(6))+" "+result.unit}
function buildQuestions(method){const ids=method==="all"?primaryIds:[method];const pool=[];ids.forEach(id=>(questionBank[id]||questionBank.ut).forEach((q,i)=>pool.push({id:id,q:q,uid:id+"-"+i})));const seen=readLocal("ndt-new-ui-used-questions",[]);const fresh=pool.filter(x=>!seen.includes(x.uid));const source=(fresh.length>=25?fresh:pool).slice();for(let i=source.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[source[i],source[j]]=[source[j],source[i]]}const selected=source.slice(0,25);if(selected.length<25){const fill=pool.slice();while(selected.length<25&&fill.length)selected.push(fill[selected.length%fill.length])}saveLocal("ndt-new-ui-used-questions",[...seen,...selected.map(x=>x.uid)].slice(-500));return selected.map(x=>({method:x.id,uid:x.uid,q:x.q[0],options:x.q.slice(1,5),correct:x.q[5],explanation:x.q[6]}))}
function beginPractice(method){state.session={method,index:0,questions:buildQuestions(method),answers:Array(25).fill(null)};state.results=null;render()}
function finishPractice(){const s=state.session;const review=s.questions.map((q,i)=>({q:q.q,options:q.options,correct:q.correct,selected:s.answers[i],explanation:q.explanation,method:q.method}));const correct=review.filter(x=>x.selected===x.correct).length;state.results={method:s.method,correct,total:review.length,percent:Math.round(correct/review.length*100),review};state.attempts.push({method:s.method,correct,total:review.length,percent:state.results.percent,date:new Date().toISOString()});saveLocal("ndt-new-ui-attempts",state.attempts);if(supabase&&state.user){supabase.from("academy_quiz_attempts").insert({user_id:state.user.id,quiz_type:"practice:"+s.method,correct_answers:correct,total_questions:review.length,score_percent:state.results.percent}).then(({error})=>{if(error)console.warn("Attempt sync did not complete:",error.message)})}state.session=null;state.view="practice-result";renderPracticeResultIntoRoot()}
function renderPracticeResultIntoRoot(){const root=$("#app");root.innerHTML=renderPracticeResult()}
function openModal(html){$("#modalContent").innerHTML=html;$("#modalBackdrop").hidden=false}
function closeModal(){$("#modalBackdrop").hidden=true}
function authModal(){if(state.user){openModal('<h2 id="modalTitle">Your account</h2><p>Signed in as '+esc(state.user.email)+'</p><div class="modal-actions"><button class="btn btn-primary" data-action="signout">Sign out</button><button class="btn btn-outline" data-action="close-modal">Close</button></div>');return}openModal('<h2 id="modalTitle">Welcome back</h2><p>Sign in to sync lesson progress and practice history across devices.</p><div class="toolbar"><button class="btn btn-primary" data-action="auth-tab" data-tab="signin">Sign in</button><button class="btn btn-outline" data-action="auth-tab" data-tab="signup">Create account</button></div><form id="authForm"><label for="authName">Full name (for new accounts)</label><input id="authName" name="name" autocomplete="name" placeholder="Your full name"><label for="authEmail">Email</label><input id="authEmail" name="email" type="email" autocomplete="email" required placeholder="you@example.com"><label for="authPassword">Password</label><input id="authPassword" name="password" type="password" autocomplete="current-password" minlength="6" required placeholder="At least 6 characters"><label for="authType">Learning profile</label><select id="authType" name="type"><option>Working Professional</option><option>Student</option><option>Other</option></select><div class="modal-actions"><button class="btn btn-primary" type="submit">Sign in</button><button class="btn btn-outline" type="button" data-action="forgot">Forgot password?</button></div><p class="small" id="authStatus"></p></form>');$("#authForm").dataset.mode="signin"}
async function syncProgress(){if(!supabase||!state.user)return;const {data,error}=await supabase.from("academy_method_lesson_progress").select("method_id,lesson_id,completed").eq("user_id",state.user.id);if(error){console.warn("Could not load cloud progress:",error.message);return}for(const row of data||[]){state.progress[row.method_id]=state.progress[row.method_id]||{};if(row.completed)state.progress[row.method_id][row.lesson_id]=true}saveLocal("ndt-new-ui-progress",state.progress);render()}
async function initAuth(){if(!supabase){$("#authButton").textContent="Local mode";return}const {data}=await supabase.auth.getSession();state.user=data.session?.user||null;updateAuthButton();if(state.user)syncProgress();supabase.auth.onAuthStateChange((_event,session)=>{state.user=session?.user||null;updateAuthButton();if(state.user)syncProgress();else render()})}
function updateAuthButton(){$("#authButton").textContent=state.user?"My account":"Sign in";if(state.view==="progress")render()}
document.addEventListener("click",async ev=>{const b=ev.target.closest("button,a");if(!b)return;
if(b.matches("[data-nav]")){ev.preventDefault();route(b.dataset.nav);$("#nav").classList.remove("open");return}
if(b.id==="mobileMenu"){$("#nav").classList.toggle("open");return}
if(b.id==="searchOpen"){$("#searchDrawer").classList.toggle("open");$("#globalSearch").focus();return}
if(b.id==="searchSubmit"){state.search=$("#globalSearch").value.trim();route("methods");return}
if(b.id==="authButton"){authModal();return}
if(b.id==="modalClose"||b.dataset.action==="close-modal"){closeModal();return}
if(b.dataset.action==="nav"){route(b.dataset.view);return}
if(b.dataset.action==="start"){startLesson(b.dataset.method);return}
if(b.dataset.action==="course"){state.method=b.dataset.method;route("course",state.method,null);return}
if(b.dataset.action==="lesson"){route("lesson",b.dataset.method,Number(b.dataset.lesson));return}
if(b.dataset.action==="continue"){const last=readLocal("ndt-new-ui-last",null);if(last)route("lesson",last.method,last.lesson);else startLesson("ut");return}
if(b.dataset.action==="complete"){saveProgress(b.dataset.method,Number(b.dataset.lesson));saveLocal("ndt-new-ui-last",{method:b.dataset.method,lesson:Number(b.dataset.lesson)});return}
if(b.dataset.action==="calculate"){calcFormula(b.dataset.id);return}
if(b.dataset.action==="formula-reset"){const f=formulas.find(x=>x.id===b.dataset.id);f.inputs.forEach(([key,,value])=>{const el=$('[data-formula-input="'+f.id+'"][data-key="'+key+'"]');if(el)el.value=value});calcFormula(f.id);return}
if(b.dataset.action==="practice-start"){beginPractice($("#practiceMethod").value);return}
if(b.dataset.action==="answer"){if(state.session)state.session.answers[state.session.index]=Number(b.dataset.answer);render();return}
if(b.dataset.action==="quiz-prev"){if(state.session&&state.session.index>0)state.session.index--;render();return}
if(b.dataset.action==="quiz-next"){if(!state.session)return;if(state.session.index<24){state.session.index++;render()}else if(confirm("Finish this 25-question practice session?"))finishPractice();return}
if(b.dataset.action==="practice-retry"){beginPractice(state.results?.method||"ut");return}
if(b.dataset.action==="auth-tab"){const form=$("#authForm");form.dataset.mode=b.dataset.tab;form.querySelector('button[type="submit"]').textContent=b.dataset.tab==="signup"?"Create account":"Sign in";$("#authName").closest("label").hidden=b.dataset.tab==="signin";$("#authName").hidden=b.dataset.tab==="signin";return}
if(b.dataset.action==="forgot"){const email=$("#authEmail").value.trim();if(!email){$("#authStatus").textContent="Enter your email address first.";return}const {error}=await supabase.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});$("#authStatus").textContent=error?error.message:"Password recovery email requested. Check your inbox.";return}
if(b.dataset.action==="signout"){await supabase?.auth.signOut();closeModal();toast("Signed out");return}
});
document.addEventListener("input",ev=>{if(ev.target.id==="methodSearch"){state.search=ev.target.value;const grid=$("#methodGrid");if(grid)grid.innerHTML=methods().filter(m=>(m.name+" "+m.code+" "+m.desc).toLowerCase().includes(state.search.toLowerCase())).map(methodCard).join("")}if(ev.target.id==="formulaSearch"){state.search=ev.target.value;render()}if(ev.target.id==="globalSearch"&&ev.key==="Enter"){$("#searchSubmit").click()}});
document.addEventListener("change",ev=>{if(ev.target.id==="formulaFilter"){state.formulaFilter=ev.target.value;render()}});
document.addEventListener("submit",async ev=>{if(ev.target.id!=="authForm")return;ev.preventDefault();const form=ev.target,mode=form.dataset.mode||"signin",email=$("#authEmail").value.trim(),password=$("#authPassword").value,name=$("#authName").value.trim(),type=$("#authType").value;const status=$("#authStatus");if(!supabase){status.textContent="Supabase is not configured. Local learning still works.";return}status.textContent="Please wait…";let result;if(mode==="signup"){result=await supabase.auth.signUp({email,password,options:{data:{full_name:name,learner_type:type},emailRedirectTo:location.origin+location.pathname}})}else{result=await supabase.auth.signInWithPassword({email,password})}if(result.error){status.textContent=result.error.message;return}if(mode==="signup"&&!result.data.session){status.textContent="Account created. Check your email to confirm the address, then sign in.";return}state.user=result.data.user||result.data.session?.user||null;updateAuthButton();if(state.user)await syncProgress();status.textContent="Success.";setTimeout(closeModal,700)});
window.addEventListener("popstate",()=>{parseRoute();render()});
window.addEventListener("error",ev=>{console.error("Academy error:",ev.message)});
